import { Injectable, NotFoundException } from '@nestjs/common';
import { NewsRepository } from './news.repository';
import { CreateNewsDto } from './dto/create-news.dto';
import { UpdateNewsDto } from './dto/update-news.dto';
import { GetNewsQueryDto } from './dto/get-news-query.dto';
import { RequestUser } from '../auth/interfaces/jwt-payload.interface';
import { RedisService } from '../redis/redis.service';
import { RoleName, NewsStatus } from '@prisma/client';
import { createPaginationResponse } from '../../common/pagination/pagination.helper';

@Injectable()
export class NewsService {
  private readonly CACHE_TTL = 600; // 10 phút

  constructor(
    private readonly newsRepository: NewsRepository,
    private readonly redisService: RedisService,
  ) {}

  async create(dto: CreateNewsDto, currentUser: RequestUser) {
    const baseSlug = this.slugify(dto.title);
    let finalSlug = baseSlug;
    const existing = await this.newsRepository.findBySlug(finalSlug);
    if (existing) {
      finalSlug = `${baseSlug}-${Date.now().toString().slice(-4)}`;
    }

    const newsInput = {
      title: dto.title,
      slug: finalSlug,
      content: dto.content,
      thumbnail: dto.thumbnail,
      status: dto.status,
      author: { connect: { id: currentUser.id } },
    };

    const news = await this.newsRepository.create(newsInput);
    await this.clearNewsListCache();
    await this.clearDashboardAndStatsCache();
    return news;
  }

  async findAll(query: GetNewsQueryDto, currentUser?: RequestUser | null) {
    const { page, limit, keyword, status } = query;

    // Chặn người dùng thường xem bản nháp (DRAFT)
    let targetStatus = status;
    if (!currentUser || currentUser.role !== RoleName.ADMIN) {
      targetStatus = NewsStatus.PUBLISHED;
    }

    const cacheKey = `news:list:k_${keyword || ''}:s_${targetStatus || 'all'}:pg_${page}:lim_${limit}`;
    const cached = await this.redisService.get(cacheKey);
    if (cached) {
      return JSON.parse(cached);
    }

    const skip = (page - 1) * limit;
    const take = limit;

    const { items, total } = await this.newsRepository.findAndCount({
      skip,
      take,
      keyword,
      status: targetStatus,
    });

    const response = createPaginationResponse(items, total, page, limit);
    await this.redisService.set(
      cacheKey,
      JSON.stringify(response),
      this.CACHE_TTL,
    );
    return response;
  }

  async findOneBySlug(slug: string, currentUser?: RequestUser | null) {
    const news = await this.newsRepository.findBySlug(slug);
    if (!news) {
      throw new NotFoundException(
        `Không tìm thấy bài viết tin tức với đường dẫn "${slug}"`,
      );
    }

    // Nếu bài viết nháp mà không phải Admin xem thì ẩn đi (404)
    if (news.status === NewsStatus.DRAFT) {
      if (!currentUser || currentUser.role !== RoleName.ADMIN) {
        throw new NotFoundException(
          `Không tìm thấy bài viết tin tức với đường dẫn "${slug}"`,
        );
      }
    }

    return news;
  }

  async update(id: string, dto: UpdateNewsDto) {
    const existing = await this.newsRepository.findById(id);
    if (!existing) {
      throw new NotFoundException(
        `Không tìm thấy bài viết tin tức với ID "${id}"`,
      );
    }

    let finalSlug = existing.slug;
    if (dto.title && dto.title !== existing.title) {
      const baseSlug = this.slugify(dto.title);
      finalSlug = baseSlug;
      const existingSlug = await this.newsRepository.findBySlug(finalSlug);
      if (existingSlug && existingSlug.id !== id) {
        finalSlug = `${baseSlug}-${Date.now().toString().slice(-4)}`;
      }
    }

    const updateData = {
      title: dto.title,
      slug: finalSlug,
      content: dto.content,
      thumbnail: dto.thumbnail,
      status: dto.status,
    };

    const updated = await this.newsRepository.update(id, updateData);
    await this.clearNewsListCache();
    await this.clearDashboardAndStatsCache();
    return updated;
  }

  async remove(id: string) {
    const existing = await this.newsRepository.findById(id);
    if (!existing) {
      throw new NotFoundException(
        `Không tìm thấy bài viết tin tức với ID "${id}"`,
      );
    }

    await this.newsRepository.softDelete(id);
    await this.clearNewsListCache();
    await this.clearDashboardAndStatsCache();
    return { id, message: 'Xóa bài viết thành công' };
  }

  private async clearNewsListCache() {
    try {
      if (this.redisService.deleteByPatterns) {
        await this.redisService.deleteByPatterns(['news:*']);
      }
      const client = this.redisService.getClient?.();
      if (client?.keys) {
        const keys = await client.keys('news:list:*');
        if (keys.length > 0) {
          await client.del(...keys);
        }
      }
    } catch {
      // Bỏ qua lỗi kết nối Redis
    }
  }

  private async clearDashboardAndStatsCache() {
    try {
      if (this.redisService.deleteByPatterns) {
        await this.redisService.deleteByPatterns([
          'dashboard:*',
          'statistics:*',
        ]);
      }
      const client = this.redisService.getClient?.();
      if (client?.keys) {
        const keys = await client.keys('dashboard:*');
        const statsKeys = await client.keys('statistics:*');
        const allKeys = [...keys, ...statsKeys];
        if (allKeys.length > 0) {
          await client.del(...allKeys);
        }
      }
    } catch {
      // Bỏ qua lỗi kết nối Redis
    }
  }

  private slugify(text: string): string {
    return text
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[đĐ]/g, 'd')
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim();
  }
}

import {
  Injectable,
  BadRequestException,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { CreateCampaignDto } from './dto/create-campaign.dto';
import { NotificationDispatcherService } from './notification-dispatcher.service';
import { RequestUser } from '../../auth/interfaces/jwt-payload.interface';
import { NotificationCampaignStatus, RoleName } from '@prisma/client';
import { createPaginationResponse } from '../../../common/pagination/pagination.helper';

@Injectable()
export class NotificationCampaignsService {
  constructor(
    private prisma: PrismaService,
    private dispatcher: NotificationDispatcherService,
  ) {}

  async create(dto: CreateCampaignDto, user: RequestUser) {
    // 1. Resolve Target Audience Users
    const targetUsers = await this.resolveTargetUsers(
      dto.targetAudience,
      dto.targetDetails,
    );

    if (targetUsers.length === 0) {
      throw new BadRequestException(
        'Không tìm thấy người nhận nào phù hợp với đối tượng mục tiêu',
      );
    }

    // 2. Determine initial status
    const isScheduled =
      !!dto.scheduledAt && new Date(dto.scheduledAt) > new Date();
    const status = isScheduled ? 'SCHEDULED' : 'SENDING';

    // 3. Create Campaign and Recipients transactionally
    const campaign = await this.prisma.$transaction(async (tx: any) => {
      const camp = await tx.notificationCampaign.create({
        data: {
          title: dto.title,
          message: dto.message,
          eventId: dto.eventId,
          targetAudience: dto.targetAudience,
          targetDetails: dto.targetDetails,
          scheduledAt: dto.scheduledAt ? new Date(dto.scheduledAt) : new Date(),
          status: status,
          totalRecipients: targetUsers.length,
          createdById: user.id,
        },
      });

      // Prepare recipient records
      const recipientData = targetUsers.map((u: any) => ({
        campaignId: camp.id,
        userId: u.id,
        deliveryStatus: 'PENDING' as any,
      }));

      // Create recipients
      await tx.notificationRecipient.createMany({
        data: recipientData,
      });

      return camp;
    });

    // 4. Trigger Dispatcher immediately if not scheduled
    if (!isScheduled) {
      // Run async
      this.dispatcher.dispatch(campaign.id).catch((e) => console.error(e));
    }

    return campaign;
  }

  async findAll(
    page: number = 1,
    limit: number = 10,
    search?: string,
    status?: NotificationCampaignStatus,
  ) {
    const skip = (page - 1) * limit;

    const where: any = {};
    if (search) {
      where.OR = [
        { title: { contains: search, mode: 'insensitive' } },
        { message: { contains: search, mode: 'insensitive' } },
      ];
    }
    if (status) {
      where.status = status;
    }

    const [items, total] = await Promise.all([
      this.prisma.notificationCampaign.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: { createdBy: { select: { fullName: true } } },
      }),
      this.prisma.notificationCampaign.count({ where }),
    ]);

    return createPaginationResponse(items, total, page, limit);
  }

  async findOne(id: string) {
    const campaign = await this.prisma.notificationCampaign.findUnique({
      where: { id },
      include: {
        createdBy: { select: { fullName: true } },
        event: { select: { title: true } },
      },
    });

    if (!campaign) throw new NotFoundException('Không tìm thấy chiến dịch');
    return campaign;
  }

  async cancel(id: string, user: RequestUser) {
    const campaign = await this.findOne(id);
    if (campaign.status !== 'DRAFT' && campaign.status !== 'SCHEDULED') {
      throw new BadRequestException(
        'Chỉ có thể hủy chiến dịch DRAFT hoặc SCHEDULED',
      );
    }

    return this.prisma.notificationCampaign.update({
      where: { id },
      data: { status: 'CANCELLED' },
    });
  }

  private async resolveTargetUsers(target: string, details?: any) {
    const where: any = { isActive: true };

    switch (target) {
      case 'SELLERS':
        where.role = { name: RoleName.SELLER };
        break;
      case 'CUSTOMERS':
        where.role = { name: RoleName.VISITOR };
        break;
      case 'ALL':
        break; // Everyone except maybe admins? We'll send to all active users.
      case 'SPECIFIC_SELLERS':
        if (!details?.sellerIds || !Array.isArray(details.sellerIds)) {
          throw new BadRequestException('Danh sách sellerIds không hợp lệ');
        }
        where.id = { in: details.sellerIds };
        break;
      case 'BUSINESSES':
        // Tương thích chiến dịch đã lưu trước migration SellerProfile.
        if (!details?.businessIds || !Array.isArray(details.businessIds)) {
          throw new BadRequestException(
            'Danh sách businessIds legacy không hợp lệ',
          );
        }
        where.businesses = { some: { id: { in: details.businessIds } } };
        break;
      case 'PROVINCES':
        if (!details?.provinceIds || !Array.isArray(details.provinceIds)) {
          throw new BadRequestException('Danh sách provinceIds không hợp lệ');
        }
        where.sellerProfile = { provinceId: { in: details.provinceIds } };
        break;
      case 'WARDS':
        if (!details?.wardIds || !Array.isArray(details.wardIds)) {
          throw new BadRequestException('Danh sách wardIds không hợp lệ');
        }
        where.sellerProfile = { wardId: { in: details.wardIds } };
        break;
      default:
        throw new BadRequestException('Đối tượng nhận không hợp lệ');
    }

    return this.prisma.user.findMany({
      where,
      select: { id: true },
    });
  }
}

