import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import {
  OrderStatus,
  PaymentMethod,
  PaymentStatus,
  Prisma,
} from '@prisma/client';

const orderShipmentInclude = Prisma.validator<Prisma.ShipmentInclude>()({
  carrierOrganization: {
    select: {
      id: true,
      code: true,
      name: true,
      providerCode: true,
      trackingUrlTemplate: true,
    },
  },
  events: {
    orderBy: [{ eventTime: 'asc' }, { createdAt: 'asc' }],
    select: {
      id: true,
      eventType: true,
      source: true,
      fromStatus: true,
      toStatus: true,
      eventTime: true,
      location: true,
      recipientName: true,
      failureReason: true,
      note: true,
      imageUrls: true,
      attachmentUrls: true,
      createdAt: true,
    },
  },
});

@Injectable()
export class OrdersRepository {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: Prisma.OrderCreateInput) {
    return this.prisma.order.create({
      data,
      include: {
        items: {
          include: {
            product: {
              select: {
                id: true,
                name: true,
                images: true,
              },
            },
          },
        },
        seller: {
          select: { id: true, fullName: true, sellerProfile: true },
        },
        tracking: {
          orderBy: { createdAt: 'asc' },
        },
        shipments: {
          include: orderShipmentInclude,
          orderBy: { createdAt: 'asc' },
        },
      },
    });
  }

  async findById(id: string) {
    return this.prisma.order.findUnique({
      where: { id },
      include: {
        items: {
          include: {
            product: {
              select: {
                id: true,
                name: true,
                images: true,
              },
            },
          },
        },
        seller: { include: { sellerProfile: true } },
        user: {
          select: {
            id: true,
            fullName: true,
            email: true,
          },
        },
        tracking: {
          orderBy: { createdAt: 'asc' },
        },
        shipments: {
          include: orderShipmentInclude,
          orderBy: { createdAt: 'asc' },
        },
      },
    });
  }

  async findByUserId(userId: string) {
    return this.prisma.order.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      include: {
        items: {
          include: {
            product: {
              select: {
                id: true,
                name: true,
                images: true,
              },
            },
          },
        },
        seller: { include: { sellerProfile: true } },
        tracking: {
          orderBy: { createdAt: 'asc' },
        },
        shipments: {
          include: orderShipmentInclude,
          orderBy: { createdAt: 'asc' },
        },
      },
    });
  }

  async findBySellerId(sellerId: string) {
    return this.prisma.order.findMany({
      where: { sellerId },
      orderBy: { createdAt: 'desc' },
      include: {
        items: {
          include: {
            product: {
              select: {
                id: true,
                name: true,
                images: true,
              },
            },
          },
        },
        user: {
          select: {
            id: true,
            fullName: true,
            email: true,
          },
        },
        seller: { include: { sellerProfile: true } },
        tracking: {
          orderBy: { createdAt: 'asc' },
        },
        shipments: {
          include: orderShipmentInclude,
          orderBy: { createdAt: 'asc' },
        },
      },
    });
  }

  async updateStatus(id: string, status: OrderStatus, description?: string) {
    return this.prisma.order.update({
      where: { id },
      data: {
        status,
        tracking: {
          create: {
            status,
            description,
          },
        },
      },
    });
  }

  async updatePaymentStatus(
    id: string,
    paymentStatus: PaymentStatus,
    vnpayTxnRef?: string,
  ) {
    return this.prisma.order.update({
      where: { id },
      data: {
        paymentStatus,
        ...(vnpayTxnRef && { vnpayTxnRef }),
      },
    });
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ForbiddenException,
  GoneException,
  Logger,
} from '@nestjs/common';
import { OrdersRepository } from './orders.repository';
import { CreateOrderDto } from './dto/create-order.dto';
import { QueryOrdersDto } from './dto/query-orders.dto';
import { UpdateOrderStatusDto } from './dto/update-order-status.dto';
import { RequestUser } from '../auth/interfaces/jwt-payload.interface';
import { OrderStatus, PaymentMethod, RoleName, Prisma } from '@prisma/client';
import { ProductsRepository } from '../products/products.repository';
import { VouchersService } from '../vouchers/vouchers.service';
import { PrismaService } from '../prisma/prisma.service';
import { SupplyChainService } from '../supply-chain/supply-chain.service';
import { NotificationsService } from '../notifications/notifications.service';
import { createPaginationResponse } from '../../common/pagination/pagination.helper';
import { InventoryReservationService } from './inventory-reservation.service';

@Injectable()
export class OrdersService {
  private readonly logger = new Logger(OrdersService.name);

  constructor(
    public readonly ordersRepository: OrdersRepository,
    private readonly productsRepository: ProductsRepository,
    private readonly vouchersService: VouchersService,
    private readonly prisma: PrismaService,
    private readonly supplyChainService: SupplyChainService,
    private readonly notificationsService: NotificationsService,
    private readonly inventoryReservations: InventoryReservationService,
  ) {}

  // ── Create Order (with inventory reserve) ────────────────────────────────

  create(dto: CreateOrderDto, user: RequestUser, ipAddress?: string) {
    void dto;
    void user;
    void ipAddress;
    throw new GoneException(
      'Endpoint tạo đơn cũ đã ngừng hoạt động. Sử dụng POST /api/v1/orders/checkout',
    );
    /* Legacy implementation retained temporarily for migration reference.
    if (!dto.items || dto.items.length === 0) {
      throw new BadRequestException('Giỏ hàng trống');
    }

    let totalAmount = 0;
    const resolvedItems: Array<{
      productId: string;
      quantity: number;
      price: number;
      reservedBatchId?: string;
      inventoryId?: string;
    }> = [];

    // ── 1. Validate products + check inventory ──────────────────────────────
    for (const item of dto.items) {
      const product = await this.productsRepository.findById(item.productId);
      if (!product) {
        throw new NotFoundException(
          `Không tìm thấy sản phẩm ID ${item.productId}`,
        );
      }

      const price = Number(product.price);
      totalAmount += price * item.quantity;

      // Check inventory availability
      const inventory = await this.prisma.inventory.findFirst({
        where: {
          productId: item.productId,
          warehouse: { managerId: { not: null } },
        },
        include: {
          batches: {
            where: { status: 'ACTIVE', quantity: { gt: 0 } },
            orderBy: { receivedDate: 'asc' }, // FIFO
          },
        },
      });

      if (inventory) {
        const available =
          inventory.currentQuantity - inventory.reservedQuantity;
        if (available < item.quantity) {
          throw new BadRequestException(
            `Sản phẩm "${product.name}" không đủ tồn kho. Khả dụng: ${available}, Yêu cầu: ${item.quantity}`,
          );
        }

        // Find earliest FIFO batch for reservation
        const firstActiveBatch = inventory.batches[0];
        resolvedItems.push({
          productId: item.productId,
          quantity: item.quantity,
          price,
          inventoryId: inventory.id,
          reservedBatchId: firstActiveBatch?.id,
        });
      } else {
        // No inventory record — allow order but don't reserve
        resolvedItems.push({
          productId: item.productId,
          quantity: item.quantity,
          price,
        });
      }
    }

    // ── 2. Vouchers ──────────────────────────────────────────────────────────
    let totalDiscount = 0;
    let platformVoucherId: string | null = null;
    let shopVoucherId: string | null = null;

    if (dto.platformVoucherCode) {
      const v = await this.vouchersService.apply({
        code: dto.platformVoucherCode,
        businessId: dto.businessId,
        orderValue: totalAmount,
      });
      totalDiscount += v.discountAmount;
      platformVoucherId = v.id;
    }

    if (dto.shopVoucherCode) {
      const v = await this.vouchersService.apply({
        code: dto.shopVoucherCode,
        businessId: dto.businessId,
        orderValue: totalAmount,
      });
      totalDiscount += v.discountAmount;
      shopVoucherId = v.id;
    }

    if (totalDiscount > totalAmount) totalDiscount = totalAmount;
    const finalAmount = totalAmount - totalDiscount;

    // ── 3. Create order + reserve inventory (in transaction) ─────────────────
    const order = await this.prisma.$transaction(async (tx) => {
      // Build order items data
      const orderItemsData: any[] = resolvedItems.map((item) => ({
        quantity: item.quantity,
        price: item.price,
        product: { connect: { id: item.productId } },
        ...(item.reservedBatchId
          ? { reservedBatch: { connect: { id: item.reservedBatchId } } }
          : {}),
      }));

      const orderData: Prisma.OrderCreateInput = {
        totalAmount: finalAmount,
        discountAmount: totalDiscount,
        shippingAddress: dto.shippingAddress,
        phone: dto.phone,
        paymentMethod: dto.paymentMethod,
        note: (dto as any).note,
        user: { connect: { id: user.id } },
        business: { connect: { id: dto.businessId } },
        items: { create: orderItemsData },
        tracking: {
          create: {
            status: 'PENDING',
            description: 'Đơn hàng đã được tạo',
            changedById: user.id,
            ipAddress: ipAddress ?? null,
          },
        },
      };

      if (platformVoucherId) {
        orderData.platformVoucher = { connect: { id: platformVoucherId } };
      }
      if (shopVoucherId) {
        orderData.shopVoucher = { connect: { id: shopVoucherId } };
      }

      const newOrder = await tx.order.create({
        data: orderData,
        include: { items: true },
      });

      // Reserve inventory: increment reservedQuantity
      for (const item of resolvedItems) {
        if (item.inventoryId) {
          await tx.inventory.update({
            where: { id: item.inventoryId },
            data: { reservedQuantity: { increment: item.quantity } },
          });
          this.logger.log(
            `Reserved ${item.quantity} units in inventory ${item.inventoryId} for order ${newOrder.id}`,
          );
        }
      }

      // Increment voucher usage
      if (platformVoucherId) {
        await this.vouchersService['vouchersRepository'].incrementUsage(
          platformVoucherId,
        );
      }
      if (shopVoucherId) {
        await this.vouchersService['vouchersRepository'].incrementUsage(
          shopVoucherId,
        );
      }

      return newOrder;
    });

    return this.ordersRepository.findById(order.id);
    */
  }

  // ── Query helpers ────────────────────────────────────────────────────────

  async getOrders(query: QueryOrdersDto, user: RequestUser) {
    const page = query.page ?? 1;
    const limit = query.limit ?? 20;
    const skip = (page - 1) * limit;

    const where: any = {};

    if (query.status) where.status = query.status;
    if (query.customerId) where.userId = query.customerId;
    if (query.sellerId) where.sellerId = query.sellerId;

    if (query.dateFrom || query.dateTo) {
      where.createdAt = {};
      if (query.dateFrom) where.createdAt.gte = new Date(query.dateFrom);
      if (query.dateTo) where.createdAt.lte = new Date(query.dateTo);
    }

    if (query.search) {
      where.OR = [
        { user: { fullName: { contains: query.search, mode: 'insensitive' } } },
        { phone: { contains: query.search } },
      ];
    }

    // Seller chỉ xem đơn hàng thuộc tài khoản của chính họ.
    if (user.role === RoleName.SELLER) {
      where.sellerId = user.id;
    } else if (user.role === RoleName.VISITOR) {
      // User can only see their own orders
      where.userId = user.id;
    }

    const [items, total] = await Promise.all([
      this.prisma.order.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: {
          items: {
            include: {
              product: {
                select: { id: true, name: true, images: { take: 1 } },
              },
              batchReservations: {
                select: {
                  quantity: true,
                  status: true,
                  batch: { select: { id: true, batchNumber: true } },
                },
              },
            },
          },
          user: {
            select: { id: true, fullName: true, email: true, phone: true },
          },
          seller: {
            select: { id: true, fullName: true, sellerProfile: true },
          },
          tracking: { orderBy: { createdAt: 'asc' } },
          shipments: {
            include: {
              carrierOrganization: {
                select: {
                  id: true,
                  code: true,
                  name: true,
                  providerCode: true,
                  trackingUrlTemplate: true,
                },
              },
              events: {
                orderBy: [{ eventTime: 'asc' }, { createdAt: 'asc' }],
                select: {
                  id: true,
                  eventType: true,
                  source: true,
                  fromStatus: true,
                  toStatus: true,
                  eventTime: true,
                  location: true,
                  recipientName: true,
                  failureReason: true,
                  note: true,
                  imageUrls: true,
                  attachmentUrls: true,
                  createdAt: true,
                },
              },
            },
            orderBy: { createdAt: 'asc' },
          },
        },
      }),
      this.prisma.order.count({ where }),
    ]);

    return createPaginationResponse(items, total, page, limit);
  }

  async getMyOrders(user: RequestUser) {
    return this.ordersRepository.findByUserId(user.id);
  }

  async getSellerOrders(user: RequestUser) {
    return this.ordersRepository.findBySellerId(user.id);
  }

  async getOrderById(id: string, user?: RequestUser) {
    const order = await this.ordersRepository.findById(id);
    if (!order) throw new NotFoundException('Không tìm thấy đơn hàng');

    // Visibility check
    if (user) {
      if (user.role === RoleName.VISITOR && order.userId !== user.id) {
        throw new ForbiddenException('Bạn không có quyền xem đơn hàng này');
      }
      if (user.role === RoleName.SELLER) {
        if (order.sellerId !== user.id) {
          throw new ForbiddenException(
            'Bạn không có quyền xem đơn hàng của gian hàng khác',
          );
        }
      }
    }

    return order;
  }

  // ── Update Order Status (with Inventory + Supply Chain side effects) ──────

  async updateOrderStatus(
    id: string,
    dto: UpdateOrderStatusDto,
    user: RequestUser,
    ipAddress?: string,
  ) {
    const newStatus = dto.status;
    const description = this.buildDescription(dto, newStatus);
    const order = await this.prisma.$transaction(async (tx) => {
      const lockMetadata = await tx.order.findUnique({
        where: { id },
        select: {
          paymentAggregateId: true,
          paymentMethod: true,
        },
      });
      if (!lockMetadata) {
        throw new NotFoundException('Không tìm thấy đơn hàng');
      }

      // Keep the same deterministic lock order as IPN/reconciliation:
      // aggregate -> transactions -> orders. This prevents a cancellation
      // racing a successful payment from releasing reservations mid-capture.
      if (lockMetadata.paymentAggregateId) {
        await tx.$queryRaw(
          Prisma.sql`SELECT "id" FROM "payment_aggregates"
            WHERE "id" = ${lockMetadata.paymentAggregateId}::uuid FOR UPDATE`,
        );
        if (
          newStatus === OrderStatus.CANCELLED &&
          lockMetadata.paymentMethod === PaymentMethod.VNPAY
        ) {
          await tx.$queryRaw(
            Prisma.sql`SELECT "id" FROM "payment_transactions"
              WHERE "payment_aggregate_id" = ${lockMetadata.paymentAggregateId}::uuid
              ORDER BY "id" FOR UPDATE`,
          );
          await tx.$queryRaw(
            Prisma.sql`SELECT "id" FROM "orders"
              WHERE "payment_aggregate_id" = ${lockMetadata.paymentAggregateId}::uuid
              ORDER BY "id" FOR UPDATE`,
          );
        } else {
          await this.inventoryReservations.lockOrder(tx, id);
        }
      } else {
        await this.inventoryReservations.lockOrder(tx, id);
      }
      const freshOrder = await tx.order.findUnique({
        where: { id },
        include: {
          items: {
            include: {
              product: true,
              batchReservations: { include: { batch: true } },
            },
          },
          seller: { include: { sellerProfile: true } },
          paymentAggregate: {
            include: { orders: { select: { id: true, status: true } } },
          },
        },
      });
      if (!freshOrder) {
        throw new NotFoundException('Không tìm thấy đơn hàng');
      }

      const isBuyerCancelling =
        user.id === freshOrder.userId && newStatus === OrderStatus.CANCELLED;
      if (
        user.role !== RoleName.ADMIN &&
        freshOrder.sellerId !== user.id &&
        !isBuyerCancelling
      ) {
        throw new ForbiddenException(
          'Bạn không có quyền cập nhật đơn hàng này',
        );
      }
      if (freshOrder.status === newStatus) {
        throw new BadRequestException(
          'Trạng thái mới phải khác trạng thái hiện tại',
        );
      }
      this.validateStatusTransition(freshOrder.status, newStatus, user.role);

      if (
        newStatus === OrderStatus.CONFIRMED &&
        freshOrder.paymentMethod === 'VNPAY' &&
        freshOrder.paymentStatus !== 'COMPLETED'
      ) {
        throw new BadRequestException(
          'Không thể xác nhận đơn VNPay trước khi IPN xác nhận thanh toán',
        );
      }

      if (
        (
          [
            OrderStatus.SHIPPED,
            OrderStatus.DELIVERED,
            OrderStatus.RETURNED,
          ] as OrderStatus[]
        ).includes(newStatus)
      ) {
        throw new BadRequestException(
          'Trạng thái vận chuyển/giao hàng/hoàn hàng chỉ được cập nhật tự động từ Shipment và bằng chứng giao nhận',
        );
      }

      if (newStatus === OrderStatus.CANCELLED) {
        const aggregate = freshOrder.paymentAggregate;
        const activeShipmentCount = await tx.shipment.count({
          where: {
            status: { not: 'CANCELLED' },
            ...(freshOrder.paymentMethod === 'VNPAY' && aggregate
              ? { order: { paymentAggregateId: aggregate.id } }
              : { orderId: id }),
          },
        });
        if (activeShipmentCount > 0) {
          throw new BadRequestException(
            'Đơn đã có chuyến hàng; Warehouse Manager phải hủy chuyến trước khi hủy đơn',
          );
        }
        if (
          freshOrder.paymentMethod === 'VNPAY' &&
          aggregate?.status === 'COMPLETED'
        ) {
          throw new BadRequestException(
            'Đơn đã thanh toán phải đi qua quy trình hoàn tiền',
          );
        }
        if (freshOrder.paymentMethod === 'VNPAY' && aggregate) {
          await tx.$queryRaw(
            Prisma.sql`SELECT "id" FROM "payment_aggregates"
              WHERE "id" = ${aggregate.id}::uuid FOR UPDATE`,
          );
          await this.inventoryReservations.releaseAggregate(tx, aggregate.id);
          const siblings = await tx.order.findMany({
            where: { paymentAggregateId: aggregate.id },
            select: { id: true, status: true },
            orderBy: { id: 'asc' },
          });
          for (const sibling of siblings) {
            if (sibling.status === OrderStatus.CANCELLED) continue;
            await tx.order.update({
              where: { id: sibling.id },
              data: {
                status: OrderStatus.CANCELLED,
                tracking: {
                  create: {
                    status: OrderStatus.CANCELLED,
                    description: 'Hủy toàn bộ checkout VNPay chưa thanh toán',
                    changedById: user.id,
                    ipAddress: ipAddress ?? null,
                  },
                },
              },
            });
          }
          await tx.paymentTransaction.updateMany({
            where: {
              paymentAggregateId: aggregate.id,
              status: 'PENDING',
            },
            data: { status: 'CANCELLED', processedAt: new Date() },
          });
          await tx.paymentAggregate.update({
            where: { id: aggregate.id },
            data: { status: 'CANCELLED', cancelledAt: new Date() },
          });
          return freshOrder;
        }
        await this.inventoryReservations.releaseOrder(tx, id);
      }

      await tx.order.update({
        where: { id },
        data: {
          status: newStatus,
          ...(newStatus === OrderStatus.DELIVERED &&
          freshOrder.paymentMethod === 'COD'
            ? { paymentStatus: 'COMPLETED' }
            : {}),
          tracking: {
            create: {
              status: newStatus,
              description,
              changedById: user.id,
              ipAddress: ipAddress ?? null,
            },
          },
        },
      });

      if (freshOrder.paymentAggregateId) {
        const activeOrders = await tx.order.findMany({
          where: {
            paymentAggregateId: freshOrder.paymentAggregateId,
            status: { not: OrderStatus.CANCELLED },
          },
          select: { status: true, totalAmount: true },
        });
        const activeAmount = activeOrders.reduce(
          (total, sibling) => total.add(sibling.totalAmount),
          new Prisma.Decimal(0),
        );
        if (newStatus === OrderStatus.CANCELLED) {
          await tx.paymentAggregate.update({
            where: { id: freshOrder.paymentAggregateId },
            data:
              activeOrders.length === 0
                ? {
                    amount: new Prisma.Decimal(0),
                    status: 'CANCELLED',
                    cancelledAt: new Date(),
                  }
                : { amount: activeAmount },
          });
        } else if (
          freshOrder.paymentMethod === 'COD' &&
          activeOrders.every((sibling) =>
            (
              [OrderStatus.DELIVERED, OrderStatus.RETURNED] as OrderStatus[]
            ).includes(sibling.status),
          )
        ) {
          await tx.paymentAggregate.update({
            where: { id: freshOrder.paymentAggregateId },
            data: { status: 'COMPLETED', completedAt: new Date() },
          });
        }
      }
      return freshOrder;
    });

    // ── Auto Supply Chain Journey (outside transaction for isolation) ─────
    await this.createAutoJourney(id, newStatus, user, order);

    // Gửi thông báo cho người mua
    const shortId = id.slice(0, 8).toUpperCase();
    await this.notificationsService.createNotification(
      order.userId,
      `Đơn hàng #${shortId} được cập nhật`,
      `Trạng thái mới: ${newStatus}. ${description}`,
      'INFO',
      '/profile/orders',
    );

    return this.ordersRepository.findById(id);
  }

  // ── Cancel Order (by customer) ────────────────────────────────────────────

  async cancelOrder(id: string, user: RequestUser, ipAddress?: string) {
    const order = await this.prisma.order.findUnique({
      where: { id },
    });

    if (!order) throw new NotFoundException('Không tìm thấy đơn hàng');

    // Only order owner can cancel (and only if PENDING or CONFIRMED)
    if (order.userId !== user.id && user.role !== RoleName.ADMIN) {
      throw new ForbiddenException('Bạn không có quyền hủy đơn hàng này');
    }

    const cancelableStatuses: OrderStatus[] = [
      OrderStatus.PENDING,
      OrderStatus.CONFIRMED,
    ];
    if (!cancelableStatuses.includes(order.status)) {
      throw new BadRequestException(
        'Chỉ có thể hủy đơn ở trạng thái Chờ xác nhận hoặc Đã xác nhận',
      );
    }

    return this.updateOrderStatus(
      id,
      { status: OrderStatus.CANCELLED, description: 'Khách hàng tự hủy đơn' },
      user,
      ipAddress,
    );
  }

  // ── Dashboard Stats ───────────────────────────────────────────────────────

  async getDashboardStats(user: RequestUser) {
    const where: any = {};

    if (user.role === RoleName.SELLER) {
      where.sellerId = user.id;
    }

    const now = new Date();
    const startOfDay = new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate(),
    );
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

    const [
      total,
      pending,
      confirmed,
      packing,
      shipped,
      delivered,
      cancelled,
      returned,
      todayOrders,
      monthOrders,
    ] = await Promise.all([
      this.prisma.order.count({ where }),
      this.prisma.order.count({ where: { ...where, status: 'PENDING' } }),
      this.prisma.order.count({ where: { ...where, status: 'CONFIRMED' } }),
      this.prisma.order.count({ where: { ...where, status: 'PACKING' } }),
      this.prisma.order.count({ where: { ...where, status: 'SHIPPED' } }),
      this.prisma.order.count({ where: { ...where, status: 'DELIVERED' } }),
      this.prisma.order.count({ where: { ...where, status: 'CANCELLED' } }),
      this.prisma.order.count({ where: { ...where, status: 'RETURNED' } }),
      this.prisma.order.count({
        where: { ...where, createdAt: { gte: startOfDay } },
      }),
      this.prisma.order.count({
        where: { ...where, createdAt: { gte: startOfMonth } },
      }),
    ]);

    // Revenue from DELIVERED orders
    const revenueResult = await this.prisma.order.aggregate({
      where: { ...where, status: 'DELIVERED' },
      _sum: { totalAmount: true },
    });

    const monthRevenueResult = await this.prisma.order.aggregate({
      where: {
        ...where,
        status: 'DELIVERED',
        createdAt: { gte: startOfMonth },
      },
      _sum: { totalAmount: true },
    });

    return {
      total,
      pending,
      confirmed,
      packing,
      shipped,
      delivered,
      cancelled,
      returned,
      todayOrders,
      monthOrders,
      totalRevenue: Number(revenueResult._sum.totalAmount ?? 0),
      monthRevenue: Number(monthRevenueResult._sum.totalAmount ?? 0),
    };
  }

  // ── Private helpers ───────────────────────────────────────────────────────

  private validateStatusTransition(
    from: OrderStatus,
    to: OrderStatus,
    role: RoleName,
  ) {
    const transitions: Partial<Record<OrderStatus, OrderStatus[]>> = {
      PENDING: [OrderStatus.CONFIRMED, OrderStatus.CANCELLED],
      CONFIRMED: [OrderStatus.PACKING, OrderStatus.CANCELLED],
      PACKING: [OrderStatus.CANCELLED],
      PROCESSING: [OrderStatus.CANCELLED], // legacy
      SHIPPED: [],
      DELIVERED: [],
      CANCELLED: [],
      RETURNED: [],
    };

    const allowed = transitions[from] ?? [];
    if (!allowed.includes(to)) {
      throw new BadRequestException(
        `Không thể chuyển từ trạng thái "${from}" sang "${to}"`,
      );
    }
  }

  private buildDescription(
    dto: UpdateOrderStatusDto,
    status: OrderStatus,
  ): string {
    const base = dto.description ?? '';

    const defaults: Partial<Record<OrderStatus, string>> = {
      CONFIRMED: 'Đơn hàng đã được xác nhận',
      PACKING: 'Đang tiến hành đóng gói',
      SHIPPED: 'Đơn hàng đã được giao cho đơn vị vận chuyển',
      DELIVERED: 'Giao hàng thành công',
      CANCELLED: 'Đơn hàng đã bị hủy',
      RETURNED: 'Khách hàng đã hoàn trả hàng',
    };

    return base || defaults[status] || status;
  }

  private async createAutoJourney(
    orderId: string,
    status: OrderStatus,
    user: RequestUser,
    order: any,
  ) {
    const journeyStatuses: OrderStatus[] = [
      OrderStatus.SHIPPED,
      OrderStatus.DELIVERED,
    ];
    if (!journeyStatuses.includes(status)) return;

    try {
      // Find stages
      const stageName =
        status === OrderStatus.SHIPPED ? 'SHIPPING' : 'CUSTOMER';

      const stage = await this.prisma.supplyChainStage.findUnique({
        where: { name: stageName as any },
      });

      if (!stage) return;

      // Get batches associated with order items
      const items = order.items ?? [];
      const batchIds = new Set<string>();

      for (const item of items) {
        for (const reservation of item.batchReservations ?? []) {
          if (reservation.batchId) batchIds.add(reservation.batchId);
        }
      }

      // If no reserved batches, try to find via inventory
      if (batchIds.size === 0) {
        for (const item of items) {
          const inv = await this.prisma.inventory.findFirst({
            where: { productId: item.productId },
            include: {
              batches: {
                where: {
                  status:
                    status === OrderStatus.SHIPPED
                      ? 'ACTIVE'
                      : { in: ['ACTIVE', 'DEPLETED'] },
                },
                orderBy: { receivedDate: 'asc' },
                take: 1,
              },
            },
          });
          if (inv?.batches[0]) batchIds.add(inv.batches[0].id);
        }
      }

      const location =
        status === OrderStatus.SHIPPED
          ? (order.seller?.sellerProfile?.address ?? 'Kho hàng')
          : (order.shippingAddress ?? 'Địa chỉ khách hàng');

      const actorName =
        status === OrderStatus.SHIPPED
          ? (order.seller?.sellerProfile?.displayName ??
            order.seller?.fullName ??
            'Nhà bán hàng')
          : (order.user?.fullName ?? 'Khách hàng');

      for (const batchId of batchIds) {
        await this.prisma.batchJourney.create({
          data: {
            batchId,
            stageId: stage.id,
            location,
            actorName,
            actorId: user.id,
            note: `Tự động từ đơn hàng #${orderId.slice(0, 8).toUpperCase()}`,
            imageUrls: [],
            attachmentUrls: [],
            blockchainPayload: {
              source: 'ORDER_AUTO',
              orderId,
              status,
              timestamp: new Date().toISOString(),
              actorId: user.id,
            },
          },
        });

        this.logger.log(
          `Auto Supply Chain Journey: batch=${batchId} stage=${stageName} order=${orderId}`,
        );
      }
    } catch (err) {
      // Non-blocking: log error but don't fail the status update
      this.logger.error(`Failed to create auto supply chain journey: ${err}`);
    }
  }
}

import { Injectable, ServiceUnavailableException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Prisma } from '@prisma/client';
import { createHmac, timingSafeEqual } from 'crypto';

type StringMap = Record<string, string>;
type JsonMap = Record<string, unknown>;

export interface VnpayPaymentUrlInput {
  txnRef: string;
  amount: Prisma.Decimal;
  ipAddress: string;
  createDate: Date;
  expiresAt: Date;
}

export interface VnpayQueryInput {
  requestId: string;
  txnRef: string;
  transactionDate: string;
  transactionNo?: string | null;
}

export interface VnpayRefundInput extends VnpayQueryInput {
  amount: Prisma.Decimal;
  transactionType: '02' | '03';
  createdBy: string;
}

export interface VnpayGatewayResult {
  signatureValid: boolean;
  responseCode: string;
  transactionStatus: string;
  transactionNo?: string;
  refundTransactionNo?: string;
  amount?: string;
  paid: boolean;
  raw: JsonMap;
}

@Injectable()
export class VnpayGateway {
  constructor(private readonly config: ConfigService) {}

  isConfigured() {
    return Boolean(
      this.config.get<string>('VNPAY_TMN_CODE')?.trim() &&
      this.config.get<string>('VNPAY_HASH_SECRET')?.trim(),
    );
  }

  buildPaymentUrl(input: VnpayPaymentUrlInput) {
    const { tmnCode, secret } = this.credentials();
    const paymentUrl = this.config.get<string>(
      'VNPAY_URL',
      'https://sandbox.vnpayment.vn/paymentv2/vpcpay.html',
    );
    const returnUrl = this.config.get<string>(
      'VNPAY_RETURN_URL',
      'http://localhost:3000/checkout/callback',
    );

    const params: StringMap = {
      vnp_Version: '2.1.0',
      vnp_Command: 'pay',
      vnp_TmnCode: tmnCode,
      vnp_Locale: 'vn',
      vnp_CurrCode: 'VND',
      vnp_TxnRef: input.txnRef,
      vnp_OrderInfo: `Thanh toan OCOP ${input.txnRef}`,
      vnp_OrderType: 'other',
      vnp_Amount: input.amount.mul(100).toFixed(0),
      vnp_ReturnUrl: returnUrl,
      vnp_IpAddr: this.normalizeIp(input.ipAddress),
      vnp_CreateDate: this.formatGatewayDate(input.createDate),
      vnp_ExpireDate: this.formatGatewayDate(input.expiresAt),
    };
    const query = this.toSignedQuery(params, secret);
    return {
      paymentUrl: `${paymentUrl}?${query}`,
      gatewayCreateDate: params.vnp_CreateDate,
    };
  }

  verifyCallback(input: Record<string, unknown>) {
    const { secret } = this.credentials();
    const secureHash = this.asString(input.vnp_SecureHash);
    const params = this.vnpStringParams(input, [
      'vnp_SecureHash',
      'vnp_SecureHashType',
    ]);
    if (!secureHash || !/^[0-9a-fA-F]{128}$/.test(secureHash)) {
      return { valid: false, params };
    }

    const expected = this.hmac(this.toQuery(params), secret);
    const receivedBuffer = Buffer.from(secureHash.toLowerCase(), 'hex');
    const expectedBuffer = Buffer.from(expected, 'hex');
    const valid =
      receivedBuffer.length === expectedBuffer.length &&
      timingSafeEqual(receivedBuffer, expectedBuffer);
    return { valid, params };
  }

  async queryTransaction(input: VnpayQueryInput): Promise<VnpayGatewayResult> {
    const { tmnCode, secret } = this.credentials();
    const createDate = this.formatGatewayDate(new Date());
    const ipAddress = this.serverIp();
    const orderInfo = `Truy van giao dich ${input.txnRef}`;
    const hashData = [
      input.requestId,
      '2.1.0',
      'querydr',
      tmnCode,
      input.txnRef,
      input.transactionDate,
      createDate,
      ipAddress,
      orderInfo,
    ].join('|');
    const body: StringMap = {
      vnp_RequestId: input.requestId,
      vnp_Version: '2.1.0',
      vnp_Command: 'querydr',
      vnp_TmnCode: tmnCode,
      vnp_TxnRef: input.txnRef,
      vnp_OrderInfo: orderInfo,
      vnp_TransactionDate: input.transactionDate,
      vnp_CreateDate: createDate,
      vnp_IpAddr: ipAddress,
      vnp_SecureHash: this.hmac(hashData, secret),
    };
    if (input.transactionNo) {
      body.vnp_TransactionNo = input.transactionNo;
    }

    const raw = await this.postGateway(body);
    return this.parseApiResult(raw, secret);
  }

  async refund(input: VnpayRefundInput): Promise<VnpayGatewayResult> {
    const { tmnCode, secret } = this.credentials();
    const createDate = this.formatGatewayDate(new Date());
    const ipAddress = this.serverIp();
    const orderInfo = `Hoan tien giao dich ${input.txnRef}`;
    const transactionNo = input.transactionNo ?? '';
    const amount = input.amount.mul(100).toFixed(0);
    const hashData = [
      input.requestId,
      '2.1.0',
      'refund',
      tmnCode,
      input.transactionType,
      input.txnRef,
      amount,
      transactionNo,
      input.transactionDate,
      input.createdBy,
      createDate,
      ipAddress,
      orderInfo,
    ].join('|');
    const body: StringMap = {
      vnp_RequestId: input.requestId,
      vnp_Version: '2.1.0',
      vnp_Command: 'refund',
      vnp_TmnCode: tmnCode,
      vnp_TransactionType: input.transactionType,
      vnp_TxnRef: input.txnRef,
      vnp_Amount: amount,
      vnp_TransactionNo: transactionNo,
      vnp_TransactionDate: input.transactionDate,
      vnp_CreateBy: input.createdBy,
      vnp_CreateDate: createDate,
      vnp_IpAddr: ipAddress,
      vnp_OrderInfo: orderInfo,
      vnp_SecureHash: this.hmac(hashData, secret),
    };

    const raw = await this.postGateway(body);
    return this.parseApiResult(raw, secret);
  }

  sanitizePayload(input: Record<string, unknown>): Prisma.InputJsonObject {
    const output: Record<string, Prisma.InputJsonValue> = {};
    for (const [key, value] of Object.entries(input)) {
      if (
        key.startsWith('vnp_') &&
        key !== 'vnp_SecureHash' &&
        key !== 'vnp_SecureHashType'
      ) {
        output[key] = this.asString(value).slice(0, 1000);
      }
    }
    return output;
  }

  formatGatewayDate(date: Date) {
    const vietnamTime = new Date(date.getTime() + 7 * 60 * 60 * 1000);
    const pad = (value: number) => String(value).padStart(2, '0');
    return `${vietnamTime.getUTCFullYear()}${pad(
      vietnamTime.getUTCMonth() + 1,
    )}${pad(vietnamTime.getUTCDate())}${pad(
      vietnamTime.getUTCHours(),
    )}${pad(vietnamTime.getUTCMinutes())}${pad(vietnamTime.getUTCSeconds())}`;
  }

  private async postGateway(body: StringMap): Promise<JsonMap> {
    const url = this.config.get<string>(
      'VNPAY_API_URL',
      'https://sandbox.vnpayment.vn/merchant_webapi/api/transaction',
    );
    const timeout = this.config.get<number>('VNPAY_API_TIMEOUT_MS', 5000);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
      if (!response.ok) {
        throw new Error(`VNPay HTTP ${response.status}`);
      }
      const parsed: unknown = await response.json();
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new Error('VNPay returned an invalid JSON body');
      }
      return parsed as JsonMap;
    } finally {
      clearTimeout(timer);
    }
  }

  private parseApiResult(raw: JsonMap, secret: string): VnpayGatewayResult {
    const fields = [
      'vnp_ResponseId',
      'vnp_Command',
      'vnp_ResponseCode',
      'vnp_Message',
      'vnp_TmnCode',
      'vnp_TxnRef',
      'vnp_Amount',
      'vnp_BankCode',
      'vnp_PayDate',
      'vnp_TransactionNo',
      'vnp_TransactionType',
      'vnp_TransactionStatus',
      'vnp_OrderInfo',
      'vnp_PromotionCode',
      'vnp_PromotionAmount',
    ];
    const hashData = fields.map((field) => this.asString(raw[field])).join('|');
    const received = this.asString(raw.vnp_SecureHash).toLowerCase();
    const expected = this.hmac(hashData, secret);
    const signatureValid =
      /^[0-9a-f]{128}$/.test(received) &&
      timingSafeEqual(
        Buffer.from(received, 'hex'),
        Buffer.from(expected, 'hex'),
      );
    const responseCode = this.asString(raw.vnp_ResponseCode);
    const transactionStatus = this.asString(raw.vnp_TransactionStatus);
    return {
      signatureValid,
      responseCode,
      transactionStatus,
      transactionNo: this.asString(raw.vnp_TransactionNo) || undefined,
      refundTransactionNo: this.asString(raw.vnp_TransactionNo) || undefined,
      amount: this.asString(raw.vnp_Amount) || undefined,
      paid:
        signatureValid && responseCode === '00' && transactionStatus === '00',
      raw: this.withoutSecureHash(raw),
    };
  }

  private toSignedQuery(params: StringMap, secret: string) {
    const query = this.toQuery(params);
    return `${query}&vnp_SecureHash=${this.hmac(query, secret)}`;
  }

  private toQuery(params: StringMap) {
    return Object.keys(params)
      .sort()
      .map((key) => `${this.encode(key)}=${this.encode(params[key] ?? '')}`)
      .join('&');
  }

  private encode(value: string) {
    return encodeURIComponent(value).replace(/%20/g, '+');
  }

  private hmac(value: string, secret: string) {
    return createHmac('sha512', secret).update(value, 'utf8').digest('hex');
  }

  private credentials() {
    const tmnCode = this.config.get<string>('VNPAY_TMN_CODE')?.trim();
    const secret = this.config.get<string>('VNPAY_HASH_SECRET')?.trim();
    if (!tmnCode || !secret) {
      throw new ServiceUnavailableException(
        'VNPay chưa được cấu hình trên máy chủ',
      );
    }
    return { tmnCode, secret };
  }

  private serverIp() {
    return this.normalizeIp(
      this.config.get<string>('VNPAY_SERVER_IP', '127.0.0.1'),
    );
  }

  private normalizeIp(value: string) {
    const normalized = value
      .split(',')[0]
      ?.trim()
      .replace(/^::ffff:/, '');
    return normalized || '127.0.0.1';
  }

  private asString(value: unknown): string {
    if (Array.isArray(value)) {
      return value.length > 0 ? this.asString(value[0]) : '';
    }
    if (typeof value === 'string') return value;
    if (
      typeof value === 'number' ||
      typeof value === 'boolean' ||
      typeof value === 'bigint'
    ) {
      return String(value);
    }
    return '';
  }

  private vnpStringParams(input: Record<string, unknown>, excluded: string[]) {
    const params: StringMap = {};
    for (const [key, value] of Object.entries(input)) {
      if (key.startsWith('vnp_') && !excluded.includes(key)) {
        params[key] = this.asString(value);
      }
    }
    return params;
  }

  private withoutSecureHash(raw: JsonMap) {
    const sanitized = { ...raw };
    delete sanitized.vnp_SecureHash;
    delete sanitized.vnp_SecureHashType;
    return sanitized;
  }
}

import {
  Controller,
  Post,
  Get,
  Patch,
  Delete,
  Param,
  Body,
  Query,
  UseGuards,
  ParseUUIDPipe,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBearerAuth,
} from '@nestjs/swagger';
import { ProductsService } from './products.service';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
