  @Get(':id')
  @UseGuards(OptionalJwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({
    summary: 'Lấy thông tin chi tiết một sản phẩm OCOP theo ID hoặc Slug',
  })
  @ApiResponse({ status: 200, description: 'Thông tin chi tiết của sản phẩm' })
