import { Controller, Get, Param, ParseUUIDPipe } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import { ProvincesService } from './provinces.service';

@ApiTags('Provinces')
@Controller('api/v1/provinces')
export class ProvincesController {
  constructor(private readonly provincesService: ProvincesService) {}

  @Get()
  @ApiOperation({
    summary:
      'Lấy danh sách 34 tỉnh/thành phố của Việt Nam (Sắp xếp theo tên tăng dần)',
  })
  @ApiResponse({
    status: 200,
    description: 'Danh sách tỉnh thành phố và tọa độ ranh giới bao quanh',
  })
  async findAll() {
    return this.provincesService.findAll();
  }

  @Get(':id')
  @ApiOperation({
    summary: 'Lấy thông tin chi tiết của một tỉnh/thành phố kèm số lượng xã',
  })
  @ApiResponse({
    status: 200,
    description: 'Thông tin chi tiết và số lượng xã trực thuộc',
  })
  @ApiResponse({ status: 404, description: 'Không tìm thấy tỉnh/thành phố' })
  async findOne(@Param('id', ParseUUIDPipe) id: string) {
    return this.provincesService.findOne(id);
  }

  @Get(':code/geojson')
  @ApiOperation({
    summary:
      'Lấy dữ liệu ranh giới địa lý chi tiết GeoJSON của tỉnh/thành phố theo mã',
  })
  @ApiResponse({
    status: 200,
    description: 'Dữ liệu tọa độ bản đồ số dạng GeoJSON',
  })
  @ApiResponse({
    status: 404,
    description: 'Không tìm thấy file ranh giới GeoJSON tương ứng',
  })
  async getGeoJson(@Param('code') code: string) {
    return this.provincesService.getGeoJson(code);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { ProvincesRepository } from './provinces.repository';
import { RedisService } from '../redis/redis.service';
import * as fs from 'fs/promises';
import { join } from 'path';

@Injectable()
export class ProvincesService {
  private readonly CACHE_KEY_LIST = 'provinces:list';
  private readonly CACHE_TTL_LIST = 3600; // 1 giờ (3600 giây)

  constructor(
    private readonly provincesRepository: ProvincesRepository,
    private readonly redisService: RedisService,
  ) {}

  async findAll() {
    const cachedData = await this.redisService.get(this.CACHE_KEY_LIST);
    if (cachedData) {
      return JSON.parse(cachedData);
    }

    const provinces = await this.provincesRepository.findAll();
    await this.redisService.set(
      this.CACHE_KEY_LIST,
      JSON.stringify(provinces),
      this.CACHE_TTL_LIST,
    );
    return provinces;
  }

  async findOne(id: string) {
    const province = await this.provincesRepository.findById(id);
    if (!province) {
      throw new NotFoundException(`Tỉnh/Thành phố có ID "${id}" không tồn tại`);
    }

    const wardsCount = await this.provincesRepository.countWards(id);
    return {
      ...province,
      wardsCount,
    };
  }

  async getGeoJson(code: string) {
    const province = await this.provincesRepository.findByCode(code);
    if (!province) {
      throw new NotFoundException(
        `Tỉnh/Thành phố có mã "${code}" không tồn tại`,
      );
    }

    const fileName = `${code}.geojson`;
    const filePath = join(
      process.cwd(),
      'assets',
      'geojson',
      'provinces',
      fileName,
    );

    try {
      const content = await fs.readFile(filePath, 'utf-8');
      return JSON.parse(content);
    } catch {
      throw new NotFoundException(
        `Không tìm thấy dữ liệu bản đồ số GeoJSON của tỉnh/thành phố mã "${code}"`,
      );
    }
  }
}

import {
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import Redis from 'ioredis';
import type { RedisOptions } from 'ioredis';
import { createRedisConnectionOptions } from './redis-connection.util';

@Injectable()
export class RedisService implements OnModuleInit, OnModuleDestroy {
  private client: Redis;
  private isConnected = false;
  private readonly logger = new Logger(RedisService.name);

  constructor(configService: ConfigService) {
    this.client = new Redis({
      ...createRedisConnectionOptions(configService),
      lazyConnect: true,
      retryStrategy: (times) => {
        if (times > 3) return null;
        return Math.min(times * 500, 2000);
      },
      enableOfflineQueue: false,
    });

    this.client.on('connect', () => {
      this.isConnected = true;
      this.logger.log('Redis connected successfully');
    });

    this.client.on('error', (error) => {
      this.isConnected = false;
      this.logger.warn(`Redis connection error: ${error.message}`);
    });

    this.client.on('close', () => {
      this.isConnected = false;
    });
  }

  async onModuleInit() {
    try {
      await this.client.connect();
    } catch {
      this.logger.warn(
        'Redis is unavailable; cache will be skipped and the application will continue running',
      );
    }
  }

  async onModuleDestroy() {
    try {
      await this.client.quit();
    } catch {
      // ignore
    }
  }

  getClient(): Redis {
    return this.client;
  }

  async get(key: string): Promise<string | null> {
    if (!this.isConnected) return null;
    try {
      return await this.client.get(key);
    } catch {
      return null;
    }
  }

  async set(key: string, value: string, ttlSeconds?: number): Promise<void> {
    if (!this.isConnected) return;
    try {
      if (ttlSeconds) {
        await this.client.set(key, value, 'EX', ttlSeconds);
      } else {
        await this.client.set(key, value);
      }
    } catch {
      // ignore
    }
  }

  async del(key: string): Promise<void> {
    if (!this.isConnected) return;
    try {
      await this.client.del(key);
    } catch {
      // ignore
    }
  }

  async deleteByPatterns(patterns: string[]): Promise<void> {
    if (!this.isConnected) return;
    try {
      for (const pattern of patterns) {
        let cursor = '0';
        do {
          const [nextCursor, keys] = await this.client.scan(
            cursor,
            'MATCH',
            pattern,
            'COUNT',
            100,
          );
          cursor = nextCursor;
          if (keys.length > 0) await this.client.unlink(...keys);
        } while (cursor !== '0');
      }
    } catch {
      // Cache invalidation must never make the primary database operation fail.
    }
  }
}

import {
  Body,
  Controller,
  Headers,
  Param,
  Post,
  Req,
  ServiceUnavailableException,
  UnauthorizedException,
  UseGuards,
} from '@nestjs/common';
import type { RawBodyRequest } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { ThrottlerGuard } from '@nestjs/throttler';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import { createHash, createHmac, timingSafeEqual } from 'crypto';
import type { Request } from 'express';
import { CarrierWebhookDto } from './dto/carrier-webhook.dto';
import { ShipmentsService } from './shipments.service';

@ApiTags('Carrier Webhooks')
@Controller('api/v1/shipments/webhooks')
@UseGuards(ThrottlerGuard)
export class CarrierWebhooksController {
  constructor(
    private readonly shipmentsService: ShipmentsService,
    private readonly config: ConfigService,
  ) {}

  @Post(':providerCode')
  @ApiOperation({
    summary: 'Webhook chuẩn hóa có chữ ký HMAC từ adapter nhà vận chuyển',
  })
  handle(
    @Param('providerCode') providerCode: string,
    @Headers('x-carrier-signature') signature: string | undefined,
    @Body() dto: CarrierWebhookDto,
    @Req() request: RawBodyRequest<Request>,
  ) {
    const normalizedProvider = providerCode.trim().toUpperCase();
    const secret = this.secretFor(normalizedProvider);
    if (!secret) {
      throw new ServiceUnavailableException(
        'Nhà vận chuyển chưa cấu hình webhook',
      );
    }
    if (!request.rawBody || !signature) {
      throw new UnauthorizedException('Thiếu chữ ký webhook');
    }
    const providedHex = signature.replace(/^sha256=/i, '').trim();
    const expected = Buffer.from(
      createHmac('sha256', secret).update(request.rawBody).digest('hex'),
      'hex',
    );
    let provided: Buffer;
    try {
      provided = Buffer.from(providedHex, 'hex');
    } catch {
      throw new UnauthorizedException('Chữ ký webhook không hợp lệ');
    }
    if (
      provided.length !== expected.length ||
      !timingSafeEqual(provided, expected)
    ) {
      throw new UnauthorizedException('Chữ ký webhook không hợp lệ');
    }
    const payloadHash = createHash('sha256')
      .update(request.rawBody)
      .digest('hex');
    return this.shipmentsService.processCarrierWebhook(
      normalizedProvider,
      dto,
      payloadHash,
    );
  }

  private secretFor(providerCode: string) {
    const raw = this.config.get<string>('CARRIER_WEBHOOK_SECRETS');
    if (!raw) return undefined;
    try {
      const values = JSON.parse(raw) as Record<string, unknown>;
      const secret = values[providerCode];
      return typeof secret === 'string' && secret.length >= 32
        ? secret
        : undefined;
    } catch {
      return undefined;
    }
  }
}

