  @Get()
  @Roles(RoleName.ADMIN)
  @ApiOperation({ summary: 'Lấy danh sách Users (Hỗ trợ lọc)' })
  @ApiQuery({
    name: 'assignable',
    required: false,
    type: Boolean,
    description: 'Lọc các user có thể assign làm Quản lý kho',
