import {
  ConflictException,
  GoneException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { Prisma, RoleName } from '@prisma/client';
import * as argon2 from 'argon2';
import { CreateWarehouseManagerDto } from './dto/create-warehouse-manager.dto';
import { CreateLogisticsUserDto } from './dto/create-logistics-user.dto';
import { RedisService } from '../redis/redis.service';

@Injectable()
export class UsersService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly redis: RedisService,
  ) {}

  async createSeller(dto: CreateWarehouseManagerDto) {
    const seller = await this.createOperationalUser(
      dto,
      RoleName.SELLER,
      'người bán',
      undefined,
      true,
    );
    await this.invalidateSellerCaches();
    return seller;
  }

  async createWarehouseManager(dto: CreateWarehouseManagerDto) {
    return this.createOperationalUser(
      dto,
      RoleName.WAREHOUSE_MANAGER,
      'quản lý kho',
    );
  }

  async createQualityAssurance(dto: CreateWarehouseManagerDto) {
    return this.createOperationalUser(dto, RoleName.QUALITY_ASSURANCE, 'QA/QC');
  }

  async getQualityAssuranceUsers(search?: string) {
    return this.prisma.user.findMany({
      where: {
        role: { name: RoleName.QUALITY_ASSURANCE },
        isActive: true,
        ...(search?.trim()
          ? {
              OR: [
                {
                  fullName: {
                    contains: search.trim(),
                    mode: 'insensitive' as const,
                  },
                },
                {
                  email: {
                    contains: search.trim(),
                    mode: 'insensitive' as const,
                  },
                },
              ],
            }
          : {}),
      },
      select: {
        id: true,
        email: true,
        fullName: true,
        phone: true,
        isActive: true,
        role: { select: { name: true } },
      },
      orderBy: { fullName: 'asc' },
    });
  }

  async updateSellerStatus(sellerId: string, isActive: boolean) {
    const seller = await this.prisma.user.findFirst({
      where: { id: sellerId, role: { name: RoleName.SELLER } },
      select: { id: true },
    });
    if (!seller) {
      throw new NotFoundException('Không tìm thấy tài khoản SELLER');
    }

    const updated = await this.prisma.user.update({
      where: { id: sellerId },
      data: { isActive },
      select: {
        id: true,
        email: true,
        fullName: true,
        phone: true,
        isActive: true,
        role: { select: { name: true } },
        sellerProfile: {
          select: { id: true, displayName: true, isVerified: true },
        },
      },
    });
    await this.invalidateSellerCaches();
    return updated;
  }

  async createLogisticsUser(dto: CreateLogisticsUserDto) {
    void dto;
    throw new GoneException(
      'Hệ thống không tạo tài khoản nhân viên vận chuyển nội bộ. Hãy cấu hình hãng vận chuyển và nhận trạng thái qua webhook/API của hãng.',
    );
  }

  private async createOperationalUser(
    dto: CreateWarehouseManagerDto,
    roleName: RoleName,
    roleLabel: string,
    logisticsOrganizationId?: string,
    createSellerProfile = false,
  ) {
    const email = dto.email.trim().toLowerCase();
    const existing = await this.prisma.user.findFirst({
      where: { email: { equals: email, mode: 'insensitive' } },
      select: { id: true },
    });
    if (existing) {
      throw new ConflictException('Email đã được sử dụng');
    }

    const role = await this.prisma.role.findUnique({
      where: { name: roleName },
      select: { id: true },
    });
    if (!role) {
      throw new ConflictException(
        `Hệ thống chưa thiết lập vai trò ${roleLabel}. Vui lòng chạy migration mới nhất.`,
      );
    }

    const passwordHash = await argon2.hash(dto.password, {
      type: argon2.argon2id,
    });

    try {
      return await this.prisma.user.create({
        data: {
          email,
          fullName: dto.fullName.trim(),
          phone: dto.phone?.trim() || null,
          passwordHash,
          isActive: true,
          mustChangePassword: true,
          role: { connect: { id: role.id } },
          ...(createSellerProfile
            ? {
                sellerProfile: {
                  create: {
                    displayName: dto.fullName.trim(),
                    email,
                    phone: dto.phone?.trim() || null,
                  },
                },
              }
            : {}),
          ...(logisticsOrganizationId
            ? {
                logisticsMemberships: {
                  create: {
                    organizationId: logisticsOrganizationId,
                    isActive: true,
                  },
                },
              }
            : {}),
        },
        select: {
          id: true,
          email: true,
          fullName: true,
          phone: true,
          isActive: true,
          mustChangePassword: true,
          role: { select: { name: true } },
          sellerProfile: {
            select: { id: true, displayName: true, isVerified: true },
          },
          logisticsMemberships: {
            where: { isActive: true },
            select: {
              organization: {
                select: { id: true, code: true, name: true, type: true },
              },
            },
          },
        },
      });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === 'P2002'
      ) {
        throw new ConflictException('Email đã được sử dụng');
      }
      throw error;
    }
  }

  async getLogisticsUsers(search?: string, organizationId?: string) {
    void search;
    void organizationId;
    throw new GoneException(
      'Danh sách nhân viên vận chuyển nội bộ đã ngừng dùng. Shipment chỉ theo dõi hãng vận chuyển và mã vận đơn.',
    );
  }

  async getUsers(
    assignable: boolean,
    search?: string,
    page: number = 1,
    limit: number = 50,
    sort: string = 'fullName',
    order: 'asc' | 'desc' = 'asc',
  ) {
    const whereClause: Prisma.UserWhereInput = {};

    if (assignable) {
      whereClause.role = {
        name: {
          in: [RoleName.WAREHOUSE_MANAGER],
        },
      };
      whereClause.isActive = true;
    }

    if (search) {
      whereClause.OR = [
        { fullName: { contains: search, mode: 'insensitive' } },
        { email: { contains: search, mode: 'insensitive' } },
      ];
    }

    const skip = (page - 1) * limit;
    const orderBy: Prisma.UserOrderByWithRelationInput =
      sort === 'email'
        ? { email: order }
        : sort === 'createdAt'
          ? { createdAt: order }
          : { fullName: order };

    const [users, total] = await Promise.all([
      this.prisma.user.findMany({
        where: whereClause,
        select: {
          id: true,
          email: true,
          fullName: true,
          role: { select: { name: true } },
          sellerProfile: { select: { displayName: true } },
        },
        skip,
        take: limit,
        orderBy,
      }),
      this.prisma.user.count({ where: whereClause }),
    ]);

    return {
      data: users,
      meta: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  private async invalidateSellerCaches() {
    await this.redis.deleteByPatterns([
      'seller-profiles:list:*',
      'products:list:*',
      'dashboard:*',
      'statistics:*',
    ]);
  }
}

import {
  Controller,
  Post,
  Get,
  Delete,
  Patch,
  Param,
  Body,
  UseGuards,
  HttpCode,
  ParseUUIDPipe,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBearerAuth,
} from '@nestjs/swagger';
import { VouchersService } from './vouchers.service';
import { CreateVoucherDto, ApplyVoucherDto } from './dto/voucher.dto';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { RolesGuard } from '../auth/guards/roles.guard';
import { Roles } from '../auth/decorators/roles.decorator';
import { CurrentUser } from '../auth/decorators/current-user.decorator';
import { RequestUser } from '../auth/interfaces/jwt-payload.interface';
import { RoleName } from '@prisma/client';

@ApiTags('Vouchers')
@Controller('api/v1/vouchers')
export class VouchersController {
  constructor(private readonly vouchersService: VouchersService) {}

  @Post()
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles(RoleName.ADMIN, RoleName.SELLER)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Tạo mã giảm giá' })
  @ApiResponse({ status: 201, description: 'Tạo thành công' })
  async create(
    @Body() dto: CreateVoucherDto,
    @CurrentUser() user: RequestUser,
  ) {
    return this.vouchersService.create(dto, user);
  }

  @Get()
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles(RoleName.ADMIN, RoleName.SELLER)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Lấy danh sách mã giảm giá' })
  async getAll(@CurrentUser() user: RequestUser) {
    return this.vouchersService.getAll(user);
  }

  @Post('apply')
  @HttpCode(200)
  @ApiOperation({ summary: 'Kiểm tra và tính toán mã giảm giá' })
  async apply(@Body() dto: ApplyVoucherDto) {
    return this.vouchersService.apply(dto);
  }

  @Delete(':id')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles(RoleName.ADMIN, RoleName.SELLER)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Xóa mã giảm giá' })
  async remove(
    @Param('id', ParseUUIDPipe) id: string,
    @CurrentUser() user: RequestUser,
  ) {
    return this.vouchersService.delete(id, user);
  }

  @Patch(':id/toggle')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles(RoleName.ADMIN, RoleName.SELLER)
  @ApiBearerAuth()
  @ApiOperation({
    summary: 'Bật hoặc tắt trạng thái hoạt động của mã giảm giá',
  })
  async toggleStatus(
    @Param('id', ParseUUIDPipe) id: string,
    @CurrentUser() user: RequestUser,
  ) {
    return this.vouchersService.toggleStatus(id, user);
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { Prisma } from '@prisma/client';

@Injectable()
export class VouchersRepository {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: Prisma.VoucherUncheckedCreateInput) {
    return this.prisma.voucher.create({ data });
  }

  async findAll(sellerId?: string) {
    const where = sellerId ? { OR: [{ sellerId }, { sellerId: null }] } : {};
    return this.prisma.voucher.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      include: {
        seller: { select: { id: true, fullName: true, sellerProfile: true } },
      },
    });
  }

  async findByCode(code: string) {
    return this.prisma.voucher.findUnique({
      where: { code },
      include: {
        seller: { include: { sellerProfile: true } },
      },
    });
  }

  async incrementUsage(id: string) {
    return this.prisma.voucher.update({
      where: { id },
      data: { usedCount: { increment: 1 } },
    });
  }

  async findById(id: string) {
    return this.prisma.voucher.findUnique({
      where: { id },
      include: {
        seller: { include: { sellerProfile: true } },
        _count: {
          select: {
            platformOrders: true,
            shopOrders: true,
          },
        },
      },
    });
  }

  async delete(id: string) {
    return this.prisma.voucher.delete({
      where: { id },
    });
  }

  async update(id: string, data: Prisma.VoucherUncheckedUpdateInput) {
    return this.prisma.voucher.update({
      where: { id },
      data,
    });
  }
}

