import { Controller, Get, Param, Query, ParseUUIDPipe } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import { WardsService } from './wards.service';
import { GetWardsQueryDto } from './dto/get-wards-query.dto';

@ApiTags('Wards')
@Controller('api/v1/wards')
export class WardsController {
  constructor(private readonly wardsService: WardsService) {}

  @Get()
  @ApiOperation({
    summary:
      'Lấy danh sách xã có phân trang, hỗ trợ lọc theo tỉnh/thành phố và tìm kiếm từ khóa',
  })
  @ApiResponse({
    status: 200,
    description: 'Danh sách xã kèm theo metadata phân trang',
  })
  async findAll(@Query() query: GetWardsQueryDto) {
    return this.wardsService.findAll({
      provinceId: query.provinceId,
      search: query.search,
      page: query.page,
      limit: query.limit,
    });
  }

  @Get(':id')
  @ApiOperation({ summary: 'Lấy thông tin chi tiết của một xã theo ID' })
  @ApiResponse({
    status: 200,
    description: 'Thông tin chi tiết xã và tỉnh thành trực thuộc',
  })
  @ApiResponse({ status: 404, description: 'Không tìm thấy xã' })
  async findOne(@Param('id', ParseUUIDPipe) id: string) {
    return this.wardsService.findOne(id);
  }

  @Get(':id/geojson')
  @ApiOperation({
    summary: 'Lấy dữ liệu ranh giới địa lý chi tiết GeoJSON của xã theo ID',
  })
  @ApiResponse({
    status: 200,
    description: 'Dữ liệu tọa độ bản đồ số dạng GeoJSON',
  })
  @ApiResponse({
    status: 404,
    description: 'Không tìm thấy file ranh giới GeoJSON tương ứng',
  })
  async getGeoJson(@Param('id', ParseUUIDPipe) id: string) {
    return this.wardsService.getGeoJson(id);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { WardsRepository } from './wards.repository';
import { RedisService } from '../redis/redis.service';
import { createPaginationResponse } from '../../common/pagination/pagination.helper';
import * as fs from 'fs/promises';
import { join } from 'path';

@Injectable()
export class WardsService {
  private readonly CACHE_TTL_LIST = 600; // 10 phút (600 giây)

  constructor(
    private readonly wardsRepository: WardsRepository,
    private readonly redisService: RedisService,
  ) {}

  async findAll(params: {
    provinceId?: string;
    search?: string;
    page: number;
    limit: number;
  }) {
    const { provinceId, search, page, limit } = params;
    const cacheKey = `wards:list:prov_${provinceId || 'all'}:search_${search || ''}:page_${page}:limit_${limit}`;

    const cachedData = await this.redisService.get(cacheKey);
    if (cachedData) {
      return JSON.parse(cachedData);
    }

    const skip = (page - 1) * limit;
    const take = limit;

    const { items, total } = await this.wardsRepository.findAndCount({
      provinceId,
      search,
      skip,
      take,
    });

    const response = createPaginationResponse(items, total, page, limit);

    await this.redisService.set(
      cacheKey,
      JSON.stringify(response),
      this.CACHE_TTL_LIST,
    );
    return response;
  }

  async findOne(id: string) {
    const ward = await this.wardsRepository.findById(id);
    if (!ward) {
      throw new NotFoundException(`Xã có ID "${id}" không tồn tại`);
    }
    return ward;
  }

  async getGeoJson(id: string) {
    const ward = await this.wardsRepository.findById(id);
    if (!ward) {
      throw new NotFoundException(`Xã có ID "${id}" không tồn tại`);
    }

    if (!ward.geojsonPath) {
      throw new NotFoundException(
        `Dữ liệu bản đồ số GeoJSON của xã ID "${id}" chưa được cấu hình`,
      );
    }

    const filePath = join(process.cwd(), ward.geojsonPath);

    try {
      const content = await fs.readFile(filePath, 'utf-8');
      return JSON.parse(content);
    } catch {
      throw new NotFoundException(
        `Không tìm thấy file ranh giới GeoJSON của xã tại đường dẫn "${ward.geojsonPath}"`,
      );
    }
  }
}
